const MENU_COMPONENT_SELECTOR = 'groupui-menu';
const TRIGGER_SLOT_SELECTOR = '[slot="trigger"]';
const ACTIVE_MENU_ATTRIBUTE = 'active-menu';
const VISIBLE_ATTRIBUTE = 'visible';

const getAllMenuHTMLElements = (host: HTMLElement): NodeListOf<HTMLGroupuiMenuElement> => {
  return host.querySelectorAll(MENU_COMPONENT_SELECTOR);
};

const updateActiveMenuAttribute = (menu: HTMLGroupuiMenuElement) => {
  const menuTrigger = menu.querySelector(TRIGGER_SLOT_SELECTOR);

  if (!menu.hasAttribute(VISIBLE_ATTRIBUTE) && menuTrigger) {
    menuTrigger.removeAttribute(ACTIVE_MENU_ATTRIBUTE);
  } else {
    if (menuTrigger) {
      menuTrigger.setAttribute(ACTIVE_MENU_ATTRIBUTE, '');
    }
  }
};

export const observeAllMenus = (host: HTMLElement, menuObserver: MutationObserver) => {
  menuObserver?.disconnect();
  getAllMenuHTMLElements(host).forEach((menu) => {
    menuObserver.observe(menu, { attributes: true, attributeFilter: [VISIBLE_ATTRIBUTE] });
  });
};

export const createMenuObserver = (): MutationObserver => {
  return new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      const menu = mutation.target as HTMLGroupuiMenuElement;
      updateActiveMenuAttribute(menu);
    });
  });
};

export const handleActiveMenuAttributes = (host: HTMLElement, menuObserver: MutationObserver) => {
  observeAllMenus(host, menuObserver);
  getAllMenuHTMLElements(host).forEach((menu) => {
    updateActiveMenuAttribute(menu);
  });
};
